    this.send("connect", {
      title: bridgeElement.title,
      description: this.#description
    })
  }

  notifyBridgeOfDisconnect() {
    this.send("disconnect")
  }

  // The description carries the raw timestamp so cached HTML stays
  // timezone-free; format it in the viewer's own timezone at send time.
